// Pick a random option (or use seed for consistency)
const selectedOption = computed(() => {
  const index = props.seed !== undefined
    ? props.seed % options.length
    : Math.floor(Math.random() * options.length);
  return options[index];
});

// Crop viewBox to actual rendered content using getBBox(), then pad to square.
const containerRef = ref<HTMLElement | null>(null);
const PADDING_RATIO = 0.08; // 8% breathing room around content

function cropToContent() {
  const container = containerRef.value;
  if (!container) return;
  const svg = container.querySelector('svg');
  if (!svg) return;

  // getBBox returns the tight bounding box of all rendered content
  const bbox = (svg as SVGSVGElement).getBBox();
  if (!bbox.width || !bbox.height) return;

  // Pad to square centered on content
  const side = Math.max(bbox.width, bbox.height);
  const pad = side * PADDING_RATIO;
  const totalSide = side + pad * 2;
  const cx = bbox.x + bbox.width / 2;
  const cy = bbox.y + bbox.height / 2;

  svg.setAttribute('viewBox', `${cx - totalSide / 2} ${cy - totalSide / 2} ${totalSide} ${totalSide}`);
}

watch(() => selectedOption.value, () => {
  nextTick(cropToContent);
}, { immediate: true });
</script>

